def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and
                        (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((color, cells))

    # A short straight object is recolored to the color of a longer object
    # containing a straight run of the same orientation.
    choices = []
    for color, cells in comps:
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        height = max(rs) - min(rs) + 1
        width = max(cs) - min(cs) + 1
        if height == 1 or width == 1:
            choices.append((len(cells), color, cells, height == 1))

    for size, color, cells, horizontal in sorted(choices):
        for other_color, other_cells in comps:
            if other_color == color:
                continue
            rows = {}
            cols = {}
            for r, c in other_cells:
                rows.setdefault(r, []).append(c)
                cols.setdefault(c, []).append(r)
            runs = rows.values() if horizontal else cols.values()
            if any(len(run) >= size for run in runs):
                out = [row[:] for row in grid]
                for r, c in cells:
                    out[r][c] = other_color
                return out

    return [row[:] for row in grid]
