                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append((color, cells))

    zeros = [cells for color, cells in components if color == 0]
    if zeros:
        key = max(zeros, key=len)
        # Select the component nearest the 0 object, excluding it.
        others = [(color, cells) for color, cells in components if color != 0]
        if others:
            def distance(cells):
                return min(abs(r-y) + abs(c-x) for r, c in key for y, x in cells)
            target_color, target = min(others, key=lambda item: distance(item[1]))
